-- ============================================================================
-- 20261004120000_blog_posts.sql
-- The blog moves out of the code and into the database, so a post can be
-- written, edited and published from /admin/blog without a deploy.
--
-- WHAT CHANGED. Until now every article was a TypeScript file in
-- lib/blog/posts/ and shipped with a deploy. The body was already structured
-- blocks rather than HTML for exactly this move: it lands in a jsonb column
-- unchanged, and the renderer does not notice.
--
-- WHO WRITES. Only the platform super_admin, through service-role server
-- actions behind requireSuperAdmin() (app/admin/blog/actions.ts). There is no
-- write policy for any other role, and the table-level grants are taken away
-- as well — a blog post is a public statement by the company.
--
-- WHO READS. Everyone, signed in or not, but only rows with status
-- "published". A draft is invisible to every role but the service role.
--
-- THE EIGHT EXISTING POSTS come in at the bottom, byte for byte as they were
-- in code (lib/blog/blog.test.ts runs the publishing checks over this very
-- list). "on conflict do nothing", so re-running this file never overwrites
-- an article that has since been edited in /admin.
--
-- ⚠️ APPLY THIS BEFORE THE APP THAT READS IT IS DEPLOYED. The new app reads
-- posts from here only; against a database without the table, the blog,
-- the sitemap and the feeds come up empty (they log, they do not crash).
--
-- Idempotent: safe to re-run in the Supabase SQL editor.
-- ============================================================================

create table if not exists public.blog_posts (
  id            uuid primary key default gen_random_uuid(),
  -- The URL segment, /blog/<slug>. Never change one after it ships: it is the
  -- address people have shared.
  slug          text not null unique
                check (slug ~ '^[a-z0-9]+(-[a-z0-9]+)*$'),
  status        text not null default 'draft'
                check (status in ('draft', 'published')),
  category      text not null
                check (category in ('ielts', 'multilevel', 'english', 'stories', 'engprogress')),
  skill         text
                check (skill in ('writing', 'reading', 'listening', 'speaking', 'cefr')),
  title         text not null,
  standfirst    text not null,
  author        text not null,
  published     date not null,
  updated       date,
  cover_kicker  text not null,
  -- {src, alt, credit?} — a photo instead of the generated cover.
  image         jsonb,
  featured      boolean not null default false,
  summary       jsonb not null default '[]'::jsonb check (jsonb_typeof(summary) = 'array'),
  faq           jsonb not null default '[]'::jsonb check (jsonb_typeof(faq) = 'array'),
  body          jsonb not null default '[]'::jsonb check (jsonb_typeof(body) = 'array'),
  -- {title, text, href, label} — the panel after the last paragraph.
  cta           jsonb,
  -- Order among posts published the same day: lower first.
  position      int not null default 0,
  created_at    timestamptz not null default now(),
  updated_at    timestamptz not null default now(),
  check (updated is null or updated >= published)
);

-- The lead story: at most one post, draft or not, may claim it. The editor
-- clears the old one before setting a new one.
create unique index if not exists blog_posts_one_featured
  on public.blog_posts (featured) where featured;

create index if not exists blog_posts_listing_idx
  on public.blog_posts (status, published desc, position);

create or replace trigger blog_posts_set_updated_at
  before update on public.blog_posts
  for each row execute function public.set_updated_at();

-- ---------- Row Level Security ----------------------------------------------
alter table public.blog_posts enable row level security;

drop policy if exists blog_posts_read_published on public.blog_posts;
create policy blog_posts_read_published on public.blog_posts
  for select to anon, authenticated
  using (status = 'published');

-- Supabase grants every new public table to anon and authenticated by
-- default. RLS already refuses their writes (no policy allows one); taking the
-- grants away as well means a mistaken policy later cannot open them.
revoke all on public.blog_posts from anon, authenticated;
grant select on public.blog_posts to anon, authenticated;
grant all on public.blog_posts to service_role;

-- ---------- The posts that were code ----------------------------------------
-- One post per line, newest first, in the order the code listed them.
insert into public.blog_posts (
  slug, status, category, skill, title, standfirst, author, published, updated,
  cover_kicker, image, featured, summary, faq, body, cta, position
)
select
  p->>'slug',
  'published',
  p->>'category',
  p->>'skill',
  p->>'title',
  p->>'standfirst',
  p->>'author',
  (p->>'published')::date,
  (p->>'updated')::date,
  p->'cover'->>'kicker',
  p->'image',
  coalesce((p->>'featured')::boolean, false),
  coalesce(p->'summary', '[]'::jsonb),
  coalesce(p->'faq', '[]'::jsonb),
  p->'body',
  p->'cta',
  ord::int
from jsonb_array_elements($posts$[
  {"slug":"multilevel-exam-explained","category":"multilevel","title":"The Multilevel exam explained: every part of the Reading and Writing papers","standfirst":"Uzbekistan's CEFR Multilevel exam is not IELTS. Here is how its Reading and Writing papers are built, part by part, and what each task asks of you.","published":"2026-09-27","author":"EngProgress team","cover":{"kicker":"B1–C1"},"skill":"cefr","summary":["The CEFR Multilevel exam is Uzbekistan's national English exam, run by the State Testing Centre (DTM), and it places candidates between B1 and C1 in a single sitting.","The Multilevel Reading paper has five parts and 35 questions, rising in difficulty from B1 in Part 1 to C1 in Part 5.","The Multilevel Writing paper has three tasks: an informal email of about 50 words, a formal email of 120 to 150 words about the same situation, and a forum post of 180 to 200 words.","The Multilevel exam reports a CEFR level rather than an IELTS band, and its papers use different formats from IELTS."],"body":[{"type":"p","text":"The Multilevel exam is Uzbekistan's national English exam, run by the State Testing Centre (DTM). Instead of a band from 0 to 9, it places you on the CEFR scale — B1, B2 or C1 — in a single sitting. It has four papers: Listening, Reading, Writing and Speaking. This guide walks through Reading and Writing part by part, because those are the two papers where knowing the format saves the most marks."},{"type":"h2","text":"Reading: five parts, 35 questions"},{"type":"p","text":"The Reading paper takes 60 minutes. The parts get harder as you go: Part 1 is written at B1, and Part 5 at C1. Every correct answer is worth one mark."},{"type":"h2","text":"Reading Part 1: gap fill (questions 1–6)"},{"type":"p","text":"A short B1 text of roughly 150 to 200 words, with six gaps. Each gap takes **exactly one word** — and the rule that makes this part different from any IELTS task is that **the missing word appears somewhere else in the same text**. You are not inventing the answer; you are finding it."},{"type":"tip","title":"Check the grammar around the gap","text":"Once you have found a likely word, make sure it fits exactly: singular or plural, the right tense, the right preposition after it. The text around each gap allows only one word."},{"type":"h2","text":"Reading Part 2: adverts and notices (questions 7–14)"},{"type":"p","text":"Eight short texts — adverts or notices, all on one theme, such as language courses or sports clubs — and ten statements labelled A to J. You match each text to the statement that describes it. Each statement is used once only, and **two statements are extra**: they match nothing, and they are there to catch you."},{"type":"h2","text":"Reading Part 3: headings (questions 15–20)"},{"type":"p","text":"One text in six paragraphs, and a list of headings with more headings than paragraphs — practice books typically give eight. Choose a heading for each paragraph. No heading can be used twice, and some are never used at all."},{"type":"h2","text":"Reading Part 4: a longer text (questions 21–29)"},{"type":"p","text":"One longer text — a story, a biography or a feature article — with nine questions in two blocks. Questions 21 to 24 are multiple choice with options A to D. Questions 25 to 29 are statements you mark **True**, **False** or **No Information**."},{"type":"p","text":"No Information works exactly like Not Given in IELTS: the text neither confirms nor contradicts the statement. The traps are the same too — see [True, False or Not Given? The question the passage never answers](/blog/true-false-not-given)."},{"type":"h2","text":"Reading Part 5: an academic text (questions 30–35)"},{"type":"p","text":"The hardest part: an academic C1 text of around 500 to 650 words. Questions 30 to 33 are a summary with four gaps, each taking **no more than one word and/or a number**, in the same order as the information in the text. Questions 34 and 35 are multiple choice, A to D."},{"type":"h2","text":"Writing: three tasks in two sections"},{"type":"p","text":"The Writing paper takes about an hour. Section 1 gives you **one situation** and asks you to write about it twice: once informally to a friend, and once formally to someone in charge. Section 2 is a separate opinion task."},{"type":"h2","text":"Writing Task 1.1: an informal email (about 50 words, B1)"},{"type":"p","text":"A short email to a friend about the situation — typically how you feel about it and what you think should happen. Friendly, direct and short: about 50 words is not much, so every sentence has to do a job."},{"type":"h2","text":"Writing Task 1.2: a formal email (120–150 words, B2)"},{"type":"p","text":"The same situation, written to a manager or an organisation: what the problem is, how it affects you, and what you would like them to do. The content overlaps with Task 1.1. What changes is **register** — the vocabulary, the grammar and the tone."},{"type":"example","title":"One situation, two emails: your sports club has suddenly raised its membership fee","rows":[{"label":"Task 1.1","text":"Hi Aziz! Have you seen the new prices at the club? I was really annoyed…"},{"label":"Task 1.2","text":"Dear Sir or Madam, I am writing to express my concern about the recent increase in membership fees…"}]},{"type":"h2","text":"Writing Task 2: a forum post (180–200 words, C1)"},{"type":"p","text":"You are taking part in an online discussion and must answer its question — for example, whether schools should replace exams with coursework — giving reasons and examples. This is the C1 task: a clear opinion, developed over 180 to 200 words, in a style suitable for a public forum."},{"type":"tip","title":"Register is part of the task","text":"An informal email to a friend written like a letter of complaint, or a formal email full of slang, has not done what the task asked — however accurate the English. Decide who you are writing to before you write the first word."},{"type":"h2","text":"Multilevel and IELTS: the differences that matter"},{"type":"list","items":["**The result.** Multilevel gives a CEFR level; IELTS gives a band from 0 to 9. The two are different scales, and converting one into the other by rule of thumb is unreliable.","**Reading.** Multilevel has five parts and 35 questions, including gap fills where the answer is in the text; IELTS Academic Reading has three passages and 40 questions.","**Writing.** Multilevel has three tasks, two of them emails in different registers; IELTS has two tasks, and neither is an informal email in Academic.","**One shared skill.** No Information in Multilevel and Not Given in IELTS test the same thing: reading only what the text actually says."]},{"type":"h2","text":"How the exam is scored"},{"type":"p","text":"Public descriptions of the exam give a score out of 75 for the whole exam, mapped to levels like this: **65–75 is C1**, **51–64 is B2**, **38–50 is B1**, and a score below 38 is below B1. Thresholds can be revised, so confirm the current ones with the State Testing Centre before you plan around a number."},{"type":"p","text":"Listening, the fourth paper we have not covered here, also has 35 questions, in six parts. The format of every paper rewards the same preparation: practise each part in its real shape until the instructions feel familiar, so your attention on exam day goes to the English, not to the rules."}],"faq":[{"q":"How many parts does the Multilevel Reading paper have?","a":"Five parts with 35 questions in total, taken in 60 minutes. The parts rise in difficulty from B1 in Part 1 to C1 in Part 5, and each correct answer is worth one mark."},{"q":"What are the writing tasks in the Multilevel exam?","a":"There are three tasks in two sections. Task 1.1 is an informal email to a friend of about 50 words, Task 1.2 is a formal email of 120 to 150 words about the same situation, and Task 2 is a forum post of 180 to 200 words giving an opinion."},{"q":"Is the Multilevel exam the same as IELTS?","a":"No. The Multilevel exam reports a CEFR level rather than an IELTS band, and its papers are built differently: Multilevel Reading has five parts and 35 questions, while IELTS Academic Reading has three passages and 40 questions."},{"q":"What score do you need for C1 in the Multilevel exam?","a":"Public descriptions of the exam put C1 at 65 to 75 out of 75, B2 at 51 to 64 and B1 at 38 to 50. Confirm the current thresholds with the State Testing Centre, as they can be revised."}],"cta":{"title":"Sit a full Multilevel Reading paper","text":"All five parts and 35 questions, generated fresh in the exam's own format, with an explanation for every answer you miss — and all three Writing tasks, marked to a CEFR level.","href":"/cefr-multilevel-practice","label":"CEFR / Multilevel practice"}},
  {"slug":"true-false-not-given","category":"ielts","title":"True, False or Not Given? The question the passage never answers","standfirst":"Most marks lost on this question type come from one habit: answering from what you know instead of from what the text says. Here is how to break it.","published":"2026-09-26","author":"EngProgress team","cover":{"kicker":"T / F / NG"},"featured":true,"skill":"reading","summary":["In IELTS Reading, a True / False / Not Given statement is judged only against what the passage says, not against what is true in the world.","A statement is Not Given when the passage discusses the topic but never makes that specific claim.","Qualifiers such as some, most, usually and only often decide whether a statement is True or False.","Yes / No / Not Given questions use the same logic, applied to the writer's opinions instead of facts."],"faq":[{"q":"What is the difference between False and Not Given in IELTS Reading?","a":"False means the passage says the opposite of the statement, or something that cannot be true at the same time. Not Given means the passage does not say either way, even if it discusses the same topic."},{"q":"Can I use my own knowledge to answer True / False / Not Given questions?","a":"No. Answer only from the passage. A statement that is true in real life is still Not Given if the passage never says it."},{"q":"Do True / False / Not Given answers follow the order of the passage?","a":"Yes. The statements follow the order of the text, so the answer to the previous statement tells you roughly where to look for the next one."}],"body":[{"type":"p","text":"Of all the question types in IELTS Reading, True / False / Not Given has a reputation for being unfair. It is not unfair. It is precise, and the precision is the point. The question is never *is this statement true?* It is this: does **this passage** confirm it, contradict it, or say nothing about it?"},{"type":"h2","text":"The three answers, defined properly"},{"type":"list","items":["**True** — the passage states the same idea, usually in different words.","**False** — the passage states the opposite, or something that cannot be true at the same time.","**Not Given** — the passage does not tell you either way. The topic may be there; this particular claim is not."]},{"type":"p","text":"That last line is where the marks go. A statement on the right topic, using words you can find in the text, can still be Not Given — because the passage never makes *that* claim."},{"type":"h2","text":"Three traps that catch good readers"},{"type":"p","text":"**1. The topic is there, the claim is not.** Suppose the passage says: *The bridge was completed in 1932 and remains the city's busiest crossing.* The statement *The bridge was expensive to build* is Not Given. Cost is a perfectly reasonable thing for a text about a bridge to discuss. This one does not."},{"type":"p","text":"**2. One small word changes the answer.** Words like *some*, *most*, *usually*, *may* and *only* carry the meaning. If the passage says *some researchers believe the diet works* and the statement says *researchers agree the diet works*, the answer is False: *some believe* and *agree* cannot both be true."},{"type":"p","text":"**3. Your own knowledge fills the gap.** You know that water boils at 100°C at sea level. If the passage never says so, a statement claiming it is Not Given — even though it is true. The test is about the text, not about the world."},{"type":"tip","title":"A quick test for Not Given","text":"Ask yourself: could the writer add one sentence that makes this statement True, and a different one that makes it False, without contradicting anything already written? If both are possible, the answer is Not Given."},{"type":"h2","text":"A routine that works under time pressure"},{"type":"list","ordered":true,"items":["Read the statement and underline the part that could be wrong: a number, a qualifier, a comparison, a cause.","Find the part of the passage about that topic. The statements follow the order of the text, so your previous answer tells you roughly where to look.","Compare only the underlined part. Ignore the rest of the sentence.","Agreement means True. A clear clash means False. Silence on that exact point means Not Given."]},{"type":"p","text":"One more rule: do not spend three minutes on a single statement. If you have read the relevant paragraph twice and still cannot find the claim, that silence is usually your answer."},{"type":"h2","text":"Yes / No / Not Given is the same skill"},{"type":"p","text":"When the questions are about the **writer's views** rather than facts, the labels change to Yes, No and Not Given. The logic does not change: does the writer agree with the statement, disagree with it, or not say?"}],"cta":{"title":"Practise with an explanation for every answer","text":"EngProgress Reading marks each answer and shows the sentence that proves it — and why the wrong option looked right.","href":"/ielts-reading-practice","label":"IELTS Reading practice"}},
  {"slug":"whats-new-at-engprogress","category":"engprogress","title":"All four IELTS skills, CEFR Multilevel and three languages: what's new at EngProgress","standfirst":"Speaking and Listening have joined Writing and Reading, Multilevel candidates have a track of their own, and the site now speaks Uzbek, English and Russian.","published":"2026-09-26","author":"EngProgress team","cover":{"kicker":"What's new"},"summary":["EngProgress offers practice for all four IELTS skills: Writing, Reading, Listening and Speaking.","EngProgress has a practice track for Uzbekistan's CEFR Multilevel (DTM) exam, covering the Reading and Writing papers.","The EngProgress interface is available in Uzbek, English and Russian, while exam content stays in English.","The EngProgress grader works from the official public band descriptors and gives the lower band when a script sits between two."],"faq":[{"q":"What does EngProgress offer?","a":"Practice for all four IELTS skills with AI feedback, a practice track for the Uzbekistan CEFR Multilevel exam, and tools for education centres to set homework and follow each student's progress."},{"q":"Is EngProgress available in Uzbek?","a":"Yes. The interface is available in Uzbek, which is the default, as well as English and Russian. Exam content and feedback stay in English, as in the real exam."},{"q":"Can I try EngProgress for free?","a":"Yes. The free IELTS writing checker works without an account, and a free account includes a monthly allowance of practice in all four skills."}],"body":[{"type":"p","text":"EngProgress started with the two skills candidates find hardest to judge for themselves: Writing and Reading. Here is what the platform covers today."},{"type":"h2","text":"All four IELTS skills"},{"type":"list","items":["**Writing** — Task 1 and Task 2, graded criterion by criterion with the evidence quoted from your own essay, plus a revision loop: rewrite the same essay and see what changed.","**Reading** — original passages with every real question type, and an explanation for each answer, including why the wrong option looked right.","**Listening** — full four-part tests with original multi-voice audio, transcripts and per-answer explanations.","**Speaking** — Part 2 cue-card practice, a full three-part mock with an AI examiner, and a speaking tutor that reacts and corrects while you talk."]},{"type":"h2","text":"A track for the Multilevel exam"},{"type":"p","text":"Candidates preparing for Uzbekistan's CEFR Multilevel (DTM) exam have their own practice, in that exam's format: **Reading** in five parts with 35 questions, and **Writing** with its three tasks, generated at your level. Multilevel Listening and Speaking are not available yet."},{"type":"h2","text":"Uzbek, English and Russian"},{"type":"p","text":"The whole interface is available in Uzbek — now the default — as well as in English and Russian. The exam content itself stays in English, because the exam does. There is a dark mode too, for evening study."},{"type":"h2","text":"A grader that would rather be strict"},{"type":"p","text":"Our grader works from the official public band descriptors and compares your writing with annotated sample essays at each band. When a script sits between two bands, it gives the lower one and tells you exactly what is missing for the higher. A band that is too generous in practice becomes a disappointment on exam day, and we would rather you heard *more work needed* from us first."},{"type":"h2","text":"For education centres"},{"type":"p","text":"Centres run their teachers, groups and student accounts on EngProgress: teachers set homework, every student in a group gets identical content, and the teacher sees a report for each assignment and each student across all four skills. See the [guide for centres](/how-to-use/education-centers)."},{"type":"h2","text":"And this blog"},{"type":"p","text":"Exam strategy, the stories behind English words, and news from us — written in English, so reading it counts as practice."}],"cta":{"title":"Try it free","text":"Paste an essay into the free checker — no account needed — or create a free account to practise all four skills.","href":"/grade","label":"Free IELTS writing checker"}},
  {"slug":"speaking-part-2-one-minute-plan","category":"ielts","title":"The one-minute plan: how to keep talking for two minutes in Speaking Part 2","standfirst":"You get a cue card, a pencil and sixty seconds. What you write in that minute decides whether you run out of things to say.","published":"2026-09-26","author":"EngProgress team","cover":{"kicker":"Part 2"},"skill":"speaking","summary":["In IELTS Speaking Part 2 you get one minute to prepare, with paper and a pencil, and then speak for up to two minutes.","The best use of the preparation minute is a map of keywords, one line per prompt, rather than full sentences.","Adding one extra line to your notes, such as a story or a comparison, gives you something to say when the prompts run out.","Part 2 is marked on the same four criteria as the rest of the Speaking test: Fluency and Coherence, Lexical Resource, Grammatical Range and Accuracy, and Pronunciation."],"faq":[{"q":"How long do you have to prepare in IELTS Speaking Part 2?","a":"One minute. You are given paper and a pencil to make notes, and then you speak for up to two minutes before the examiner stops you."},{"q":"What should I write in the one-minute preparation for Part 2?","a":"Write keywords, not sentences: one short line for each prompt on the card, plus one extra idea such as a story or a comparison to use if you run out of things to say."},{"q":"Should I memorise answers for IELTS Speaking Part 2?","a":"No. Rehearsed answers are easy to recognise and rarely fit the card you are actually given. Practise speaking from notes with a timer instead."}],"body":[{"type":"p","text":"In Part 2 of the Speaking test the examiner gives you a card with a topic and a few prompts. You have one minute to prepare, with paper and a pencil for notes. Then you speak for up to two minutes — the examiner will stop you — and may ask one or two short questions afterwards."},{"type":"p","text":"Most candidates do not struggle in Part 2 because their English is weak. They struggle because they finish in forty seconds and sit in silence, or because they spend the minute writing full sentences and then read them out."},{"type":"h2","text":"Do not write sentences. Write a map."},{"type":"p","text":"Sixty seconds is enough for about a dozen words. Use them for **keywords you can talk around**, not for a script. One line per prompt works well, plus one extra line nobody asked for."},{"type":"example","title":"Describe a place you visited that you would like to go back to","rows":[{"label":"Where","text":"Samarkand — Registan, early morning"},{"label":"When, who","text":"school trip, a teacher who knew the history"},{"label":"What","text":"tilework, bread market, got lost from the group"},{"label":"Why return","text":"saw it in a rush — want the evening light"},{"label":"Extra","text":"grandfather's story about the square"}]},{"type":"p","text":"The extra line matters most. When you reach the end of the prompts with forty seconds left, it is what you talk about next — a story, a comparison, a feeling."},{"type":"h2","text":"Four moves that buy you time naturally"},{"type":"list","items":["**Set the scene** before you answer: when it was, who you were with, what the weather was like. It is relevant, and it is easy to say.","**Give an example** for every general statement. *The food was good* is four words. What you ate, and where, is thirty.","**Compare** then and now, or this place and another one.","**Say how you felt, and why.** Feelings are where the less common vocabulary lives."]},{"type":"tip","title":"Practise with a timer — out loud","text":"Planning in your head is a different skill. Set one minute to plan and two to speak, record yourself, and listen back for long pauses and repeated words."},{"type":"h2","text":"What the examiner is listening for"},{"type":"p","text":"Part 2 is assessed on the same four criteria as the rest of the test: Fluency and Coherence, Lexical Resource, Grammatical Range and Accuracy, and Pronunciation. The long turn is your best chance to show **fluency** — speaking at length without obvious effort — and **coherence**, which simply means being easy to follow. Signposts help: *The main reason was…*, *What surprised me was…*, *Looking back…*"},{"type":"p","text":"And do not memorise an answer. Rehearsed speech is easy to recognise, and a prepared story rarely fits the card you are actually given."}],"cta":{"title":"Try a Part 2 card now","text":"Practise Part 2 with a cue card and a timer, or sit the full three-part speaking mock with an AI examiner.","href":"/ielts-speaking-practice","label":"IELTS Speaking practice"}},
  {"slug":"words-with-surprising-pasts","category":"stories","title":"Eight everyday English words with surprising pasts","standfirst":"A little mouse under your skin, a ball of thread in a labyrinth, forty days waiting off the coast of Venice. The stories behind common words make them easier to remember.","published":"2026-09-26","author":"EngProgress team","cover":{"kicker":"clue"},"summary":["The word quarantine comes from the Venetian quaranta giorni, meaning forty days, the waiting period for ships during plague outbreaks.","The word muscle comes from the Latin musculus, meaning little mouse.","The word clue comes from clew, a ball of thread, after the thread Theseus used to escape the labyrinth in the Greek myth.","Learning the origin of a word gives it a story, and a story makes new vocabulary easier to remember."],"faq":[{"q":"Where does the word quarantine come from?","a":"From the Venetian quaranta giorni, meaning forty days: the period ships from plague-hit places had to wait before anyone could come ashore."},{"q":"What did the word nice originally mean?","a":"It comes from the Latin nescius, meaning not knowing, and in the 1300s it meant foolish. Over the centuries it passed through meanings such as shy, fussy and precise before it came to mean pleasant."},{"q":"Does learning word origins help with IELTS vocabulary?","a":"It helps you remember words and use them precisely, which is what the Lexical Resource criterion rewards. Etymology itself is not tested."}],"body":[{"type":"p","text":"Words change. Some drift slowly; others pick up a story on the way. Knowing where a word came from is more than trivia — a story is a hook, and hooks are how vocabulary sticks."},{"type":"h2","text":"Quarantine — forty days"},{"type":"p","text":"In the 14th century, Mediterranean ports began making ships from plague-hit places wait before anyone could come ashore. Ragusa, today's Dubrovnik, set a waiting period in 1377; the forty-day version became associated with Venice, where *quaranta giorni* means forty days. The word for waiting came from the number."},{"type":"h2","text":"Muscle — a little mouse"},{"type":"p","text":"Latin *musculus* meant little mouse. A muscle moving under the skin was compared to a mouse moving under a cloth, and the name stayed."},{"type":"h2","text":"Clue — a ball of thread"},{"type":"p","text":"A *clew* was a ball of thread. In the Greek myth, Theseus unwinds one to find his way back out of the Minotaur's labyrinth. So a clew became anything that guides you through a puzzle, and the spelling became *clue*."},{"type":"h2","text":"Nice — ignorant"},{"type":"p","text":"From Latin *nescius*, not knowing. In the 1300s *nice* meant foolish. Over the centuries it passed through shy, fussy and precise — you can still make *a nice distinction* — before settling on pleasant."},{"type":"h2","text":"Silly — blessed"},{"type":"p","text":"Old English *sælig* meant happy or blessed; German *selig* still does. In English it slid to innocent, then to pitiable, and finally to foolish."},{"type":"h2","text":"Disaster — a bad star"},{"type":"p","text":"From Italian *disastro*, an ill-starred event — *astro* is star. The word carries an old belief that the positions of the stars and planets could bring misfortune."},{"type":"h2","text":"Robot — forced labour"},{"type":"p","text":"From Czech *robota*, forced work. It reached English through Karel Čapek's 1920 play *R.U.R.*, about artificial workers; Čapek said the word was his brother Josef's idea."},{"type":"h2","text":"Goodbye — God be with you"},{"type":"p","text":"A 16th-century contraction of *God be with ye*, gradually reshaped to match greetings like *good day* and *good night*."},{"type":"quote","text":"The habit behind these stories — noticing a word, connecting it to others, asking why — is how vocabulary grows from good and bad to precise, natural choices."},{"type":"tip","title":"Try it this week","text":"Next time you meet a new word, look up its origin in a good dictionary. It takes thirty seconds, and the story is often the thing you still remember a week later."}],"cta":{"title":"Put new words to work","text":"Write a Task 2 essay and see how your vocabulary is judged under Lexical Resource, with the exact phrases quoted back to you.","href":"/ielts-writing-practice","label":"IELTS Writing practice"}},
  {"slug":"plan-task-2-in-five-minutes","category":"ielts","title":"How to plan an IELTS Task 2 essay in five minutes","standfirst":"Five minutes of planning feels like time you cannot spare. It is the best-spent five minutes of the Writing test — here is what to do with them.","published":"2026-09-26","author":"EngProgress team","cover":{"kicker":"Task 2"},"skill":"writing","summary":["IELTS Writing Task 2 counts for twice as much as Task 1 and needs at least 250 words, so it deserves about 40 of the 60 minutes.","Spending the first five minutes of Task 2 on a plan keeps the essay's position consistent from introduction to conclusion.","An essay that answers only one part of a two-part Task 2 question is capped on Task Response, however good its English.","Two well-developed ideas, each with an explanation and an example, are stronger than four ideas that are only mentioned."],"faq":[{"q":"How long should I spend planning an IELTS Task 2 essay?","a":"About five minutes. Use them to identify the question type, decide your position, choose two main ideas with examples, and check the plan against every part of the prompt."},{"q":"How many words should an IELTS Task 2 essay have?","a":"At least 250 words. Task 2 counts for twice as much as Task 1, so it should get about 40 of the 60 minutes in the Writing test."},{"q":"Do memorised templates help in IELTS Writing Task 2?","a":"No. Sentences that could open any essay add no ideas about the question you were given, and a response built mostly from memorised material is marked down on Task Response."}],"body":[{"type":"p","text":"Task 2 counts for twice as much as Task 1, so it deserves about forty of your sixty minutes, and at least 250 words. Spend the first five of those minutes planning. Candidates who start writing immediately usually change their mind halfway through — and an essay that changes its mind is the one thing Task Response does not forgive."},{"type":"h2","text":"Minute 1: find every question inside the question"},{"type":"p","text":"Read the prompt twice and name its type. *To what extent do you agree?* wants a position. *Discuss both views and give your own opinion* wants both sides **and** your view. *Advantages and disadvantages*, *causes and solutions*, and prompts that ask two direct questions each want every part answered."},{"type":"p","text":"Underline each part. An essay that answers half of a two-part question is capped on Task Response, however good its English."},{"type":"h2","text":"Minute 2: decide what you think, and say it early"},{"type":"p","text":"The public band descriptors ask, at Band 7, for a clear position *throughout* the response. That means your view appears in the introduction, stays the same in every body paragraph, and returns in the conclusion. You do not need to believe it. You need to hold it for 250 words."},{"type":"h2","text":"Minutes 3 and 4: two ideas, each with an example"},{"type":"p","text":"One main idea per body paragraph, developed rather than listed: the claim, why it is true, an example, and a line tying it back to the question. Two well-developed ideas beat four mentioned ones."},{"type":"example","title":"Some people think museums should be free to enter. To what extent do you agree?","rows":[{"label":"Position","text":"Agree, with one exception"},{"label":"Paragraph 1","text":"Free entry widens access — students, families; example: school visits"},{"label":"Paragraph 2","text":"Money can come from elsewhere — donations, shops, charging for special exhibitions"},{"label":"Exception","text":"Small private museums may not survive without tickets"}]},{"type":"h2","text":"Minute 5: check the plan against the prompt"},{"type":"p","text":"Read the question one more time and tick each underlined part against your plan. This is the moment to catch the missing half of a two-part question — not in minute 38."},{"type":"tip","title":"Leave the template at home","text":"An opening like *This is a controversial issue that has sparked heated debate* could sit on top of any essay, which is exactly why it says nothing about yours. Memorised sentences add no ideas, and a response built mostly from them is marked down on Task Response."}],"cta":{"title":"See where your essay stands","text":"Paste a Task 2 essay into the free checker and get a band for each criterion, with the evidence behind it and what holds it back.","href":"/grade","label":"Free IELTS writing checker"}},
  {"slug":"why-english-spelling-is-strange","category":"english","title":"Why English spelling is so strange — and why it is not your fault","standfirst":"Knight, island, debt, colonel. English spelling looks random because much of it records how the language sounded centuries ago. The history makes it easier to learn.","published":"2026-09-26","author":"EngProgress team","cover":{"kicker":"knight"},"summary":["English spelling often records how words were pronounced centuries ago, before sounds such as the k in knight disappeared from speech.","The Great Vowel Shift, roughly between 1400 and 1700, changed the pronunciation of English long vowels while spellings were becoming fixed.","Some silent letters were added on purpose by scholars, such as the b in debt and doubt, to show a Latin origin.","In IELTS Listening and Reading a misspelt answer is marked wrong, and British and American spellings are both accepted if used consistently."],"faq":[{"q":"Why does English have so many silent letters?","a":"Many silent letters were once pronounced, like the k in knight, and stayed in the spelling after the sound was lost. Others, like the b in debt, were added by scholars to show a word's Latin origin."},{"q":"Does spelling matter in the IELTS exam?","a":"Yes. In Listening and Reading a misspelt answer is marked wrong. In Writing, spelling errors count under Lexical Resource."},{"q":"Can I use American spelling in IELTS?","a":"Yes. British and American spellings are both accepted. Choose one and use it consistently."}],"body":[{"type":"p","text":"If you have ever wondered why *knight* has a *k* nobody says, or why *colonel* sounds like *kernel*, you are asking a good question. The short answer: English spelling mostly stopped changing a few hundred years ago, and the pronunciation did not."},{"type":"h2","text":"The letters used to be pronounced"},{"type":"p","text":"In medieval English the *k* in *knight* and *knee* was pronounced, and the *gh* was a sound like the one at the end of the Scottish *loch*. Those sounds disappeared from speech, but by then the spellings were written down, copied and printed — and they stayed."},{"type":"h2","text":"The vowels moved"},{"type":"p","text":"Between roughly 1400 and 1700, the long vowels of English shifted in a change linguists call the **Great Vowel Shift**. Before it, *bite* sounded close to modern *beet*, and *name* had a vowel close to the one in *father*. Printing arrived in England in the 1470s, in the middle of that change, and helped to fix spellings that recorded the older sounds. That is a large part of why English vowels are spelt so differently from the way they are said."},{"type":"h2","text":"Some letters were added on purpose"},{"type":"p","text":"In the 1500s and 1600s, scholars who admired Latin added letters to show where words came from. *Dette* became *debt* to echo Latin *debitum*; *doute* became *doubt* after *dubitare*. The *b* was never pronounced. *Island* gained its *s* by association with *isle*, even though the two words have different origins."},{"type":"p","text":"*Colonel* is stranger still. English borrowed the word in two forms, one closer to French *coronel* and one to Italian *colonnello*. The spelling settled on one, the pronunciation on the other."},{"type":"h2","text":"Then the dictionaries arrived"},{"type":"p","text":"Samuel Johnson's *Dictionary of the English Language* (1755) did much to settle British spelling. In the United States, Noah Webster's dictionary of 1828 promoted simpler forms — *color*, *center*, *program* — which is why British and American spelling still differ today."},{"type":"tip","title":"Spelling in the IELTS exam","text":"In Listening and Reading, a misspelt answer is marked wrong, so spelling is worth practising. British and American spellings are both accepted — just be consistent. In Writing, spelling errors count under Lexical Resource."},{"type":"h2","text":"Use the history to remember"},{"type":"p","text":"Silent letters are often loud in a related word. Learn words in families and the spelling starts to make sense:"},{"type":"example","rows":[{"label":"sign","text":"signature, signal — you can hear the *g*"},{"label":"muscle","text":"muscular — you can hear the *c*"},{"label":"bomb","text":"bombard — you can hear the *b*"},{"label":"column","text":"columnist — you can hear the *n*"}]},{"type":"p","text":"English spelling is not random. It is history that nobody tidied up — and once you can see the history, it is much easier to remember."}],"cta":{"title":"Build vocabulary as you practise","text":"Save new words from any reading passage and review them later in your own vocabulary list.","href":"/ielts-reading-practice","label":"IELTS Reading practice"}},
  {"slug":"one-skill-retake","category":"ielts","title":"One Skill Retake: when resitting a single IELTS skill makes sense","standfirst":"Missed your target in just one skill? You may not need to sit the whole test again. What One Skill Retake is, and how to decide whether to use it.","published":"2026-09-26","author":"EngProgress team","cover":{"kicker":"1 skill"},"summary":["IELTS One Skill Retake lets a candidate resit one of the four skills instead of the whole test, at test centres that offer it.","The retake is taken on computer, within a limited window after the original test, and can be used once for each original test.","Not every university, employer or visa authority accepts One Skill Retake results, so acceptance should be checked before booking.","A retake is most worthwhile when only one skill is below target and the reason for the low score is known."],"faq":[{"q":"What is IELTS One Skill Retake?","a":"It is an option to retake one of the four IELTS skills, Listening, Reading, Writing or Speaking, instead of sitting the whole test again. It is available at test centres that offer it."},{"q":"Is IELTS One Skill Retake accepted by universities?","a":"Not by all of them. Check with the university, employer or visa authority you are applying to before you book, as well as the current rules on the official IELTS website."},{"q":"When is it worth using One Skill Retake?","a":"When only one skill is below your target and you know what held it back. If several skills are low, or you do not know why, a retake tends to produce the same score again."}],"body":[{"type":"p","text":"It is one of the most frustrating results in IELTS: three skills at or above your target, and one half a band short. For years the only answer was to sit all four again. **One Skill Retake** changes that at test centres that offer it."},{"type":"h2","text":"What it is"},{"type":"list","items":["You retake **one** of the four skills — Listening, Reading, Writing or Speaking — instead of the whole test.","The retake has to be booked within a limited window after your original test (IELTS gives this as 60 days).","It is taken on computer, and you can use it once for each original test.","You receive a new result for that skill alongside your original scores, and you choose which results to send."]},{"type":"tip","title":"Check two things before you book","text":"First, whether your test centre offers One Skill Retake, and at what price. Second, whether the university, employer or visa authority you are applying to **accepts** it — not every organisation does. The official IELTS website and the organisation's admissions page are the places to confirm both."},{"type":"h2","text":"When it makes sense"},{"type":"p","text":"A retake is worth it when the gap is **small and specific**. If Writing came back at 6.0 and you need 6.5, and you can name what held it back — an unclear position, underdeveloped paragraphs, the same grammar errors repeating — a focused month on that one skill is a better use of time than re-preparing for four."},{"type":"p","text":"It makes less sense when more than one skill is below target, or when you do not yet know *why* the score was low. Resitting without a diagnosis tends to produce the same band again."},{"type":"h2","text":"Use the window well"},{"type":"list","ordered":true,"items":["Find out what capped the score. For Writing and Speaking, that means the criterion — Task Response, Coherence, vocabulary, grammar — not just the overall band.","Practise that criterion on fresh material, not on tasks you have already seen.","Sit at least one full timed section before the retake, under exam conditions."]},{"type":"p","text":"The skill-by-skill view matters more with this option than without it. The better you know which part of which skill is holding you back, the more a single retake can do."}],"cta":{"title":"Find the one thing holding your band back","text":"EngProgress tracks your band per skill and, in Writing, per criterion — so you can see what to fix before you book.","href":"/ielts-practice","label":"IELTS practice, all four skills"}}
]$posts$::jsonb) with ordinality as e(p, ord)
on conflict (slug) do nothing;
